import AlchemystAI from '@alchemystai/sdk';

const apiKey = process.env.ALCHEMYST_AI_API_KEY;
const runId = process.env.ZEALT_RUN_ID;

if (!apiKey) {
  console.error("Error: ALCHEMYST_AI_API_KEY is not set.");
  process.exit(1);
}

if (!runId) {
  console.error("Error: ZEALT_RUN_ID is not set.");
  process.exit(1);
}

const client = new AlchemystAI({ apiKey });
const fileName = `policy-${runId}.md`;

async function delay(ms: number) {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

async function main() {
  console.log(`Starting run with ID: ${runId}`);
  console.log(`Target file name: ${fileName}`);

  // Step 0: Best-effort pre-cleanup delete
  console.log("Step 0: Best-effort pre-cleanup delete...");
  try {
    await client.v1.context.delete({
      source: fileName,
      by_doc: true,
      by_id: false,
    } as any);
    console.log("Pre-cleanup delete call sent.");
  } catch (error: any) {
    console.log(`Pre-cleanup delete failed (this is expected if file doesn't exist): ${error.message || error}`);
  }

  // Optional extra pre-cleanup delete using metadata just in case
  try {
    await client.v1.context.delete({
      metadata: {
        file_name: fileName,
        fileName: fileName,
      },
      by_doc: true,
      by_id: false,
    } as any);
    console.log("Pre-cleanup delete with metadata sent.");
  } catch (error: any) {
    console.log(`Pre-cleanup delete with metadata failed: ${error.message || error}`);
  }

  await delay(2000);

  // Step 1: Add first version of a document ("v1")
  console.log("Step 1: Adding document v1...");
  const addV1Response = await client.v1.context.add({
    context_type: 'resource',
    source: 'documentation',
    scope: 'internal',
    documents: [
      {
        content: "Our refund policy: We offer a 14-day money back guarantee. Contact support@example.com for refunds.",
      }
    ],
    metadata: {
      file_name: fileName,
    } as any
  });
  console.log("Document v1 added successfully:", JSON.stringify(addV1Response));

  await delay(2000);

  // Step 2: Attempt to add the same file_name again and confirm duplicate rejection (409 Conflict)
  console.log("Step 2: Attempting duplicate add (expecting 409 Conflict)...");
  try {
    await client.v1.context.add({
      context_type: 'resource',
      source: 'documentation',
      scope: 'internal',
      documents: [
        {
          content: "Our refund policy: We offer a 14-day money back guarantee. Contact support@example.com for refunds.",
        }
      ],
      metadata: {
        file_name: fileName,
      } as any
    });
    console.log("WARNING: Duplicate add did not fail!");
  } catch (error: any) {
    console.log(`Successfully caught expected error: ${error.message || error}`);
    // Check if error message or status contains 409
    const errStr = JSON.stringify(error) + " " + error.message + " " + error.status;
    console.log(`Error details: ${errStr}`);
    if (errStr.includes("409")) {
      console.log("Confirmed: Platform rejected duplicate with a 409 Conflict.");
    } else {
      console.log("Warning: Error did not explicitly mention 409, but was caught.");
    }
  }

  // Step 3: Delete the existing document by file_name
  console.log("Step 3: Deleting existing document...");
  // Let's try both deletion patterns to be absolutely safe
  try {
    await client.v1.context.delete({
      source: fileName,
      by_doc: true,
      by_id: false,
    } as any);
    console.log("Deletion by source (file_name) sent.");
  } catch (error: any) {
    console.log(`Deletion by source failed: ${error.message || error}`);
  }

  try {
    await client.v1.context.delete({
      metadata: {
        file_name: fileName,
        fileName: fileName,
      },
      by_doc: true,
      by_id: false,
    } as any);
    console.log("Deletion by metadata sent.");
  } catch (error: any) {
    console.log(`Deletion by metadata failed: ${error.message || error}`);
  }

  console.log("Waiting for deletion propagation...");
  await delay(2500);

  // Step 4: Add second version of the document ("v2") under the same file_name
  console.log("Step 4: Adding document v2...");
  const addV2Response = await client.v1.context.add({
    context_type: 'resource',
    source: 'documentation',
    scope: 'internal',
    documents: [
      {
        content: "Our refund policy: We offer a 30-day money back guarantee. Contact support@example.com for refunds.",
      }
    ],
    metadata: {
      file_name: fileName,
    } as any
  });
  console.log("Document v2 added successfully:", JSON.stringify(addV2Response));

  console.log("Waiting for indexing propagation...");
  await delay(2500);

  // Step 5: Search the context engine for v2 and print resulting content
  console.log("Step 5: Searching for v2 content...");
  const searchResponse = await client.v1.context.search({
    query: "refund policy",
    similarity_threshold: 0.5,
    minimum_similarity_threshold: 0.5,
    scope: 'internal',
    metadata: {
      fileName: fileName,
    },
    body_metadata: {
      fileName: fileName,
    }
  } as any);

  console.log("Search response:", JSON.stringify(searchResponse));

  const contexts = searchResponse.contexts || [];
  if (contexts.length > 0) {
    console.log("Top search result content:");
    console.log(contexts[0].content);
  } else {
    console.log("No contexts found in search response!");
  }
}

main().catch((err) => {
  console.error("Unhandle error in main:", err);
  process.exit(1);
});

