  } catch (e: any) {
    console.log("view.docs failed:", e.message || e);
  }

  try {
    const tracesRes = await client.v1.context.traces.list();
    console.log("traces.list res:", JSON.stringify(tracesRes, null, 2));
  } catch (e: any) {
    console.log("traces.list failed:", e.message || e);
  }
}

main();

import AlchemystAI from '@alchemystai/sdk';

const apiKey = process.env.ALCHEMYST_AI_API_KEY;
const runId = process.env.ZEALT_RUN_ID || 'test';
const client = new AlchemystAI({ apiKey });
const fileName = `policy-test-${Date.now()}.md`;

async function main() {
  console.log("Adding test document...");
  const addRes = await client.v1.context.add({
    context_type: 'resource',
    source: 'documentation',
    scope: 'internal',
    documents: [
      {
        content: "This is a temporary test document to verify deletion behavior.",
      }
    ],
    metadata: {
      fileName: fileName,
      file_name: fileName,
      fileSize: 100,
      fileType: 'text/markdown',
      lastModified: new Date().toISOString(),
    } as any
  });
  console.log("Add response:", JSON.stringify(addRes, null, 2));

  console.log("Waiting 2s...");
  await new Promise(resolve => setTimeout(resolve, 2000));

  console.log("Attempting deletion with source: 'documentation' and metadata.file_name...");
  try {
    const deleteRes = await client.v1.context.delete({
      source: 'documentation',
      by_doc: true,
      by_id: false,
      metadata: {
        file_name: fileName,
        fileName: fileName,
      }
    } as any);
    console.log("Delete response:", JSON.stringify(deleteRes, null, 2));
  } catch (e: any) {
    console.log("Delete failed:", e.message || e);
  }

  console.log("Waiting 2s...");
  await new Promise(resolve => setTimeout(resolve, 2000));

  console.log("Searching for the document...");
  const searchRes = await client.v1.context.search({
    query: "temporary test document",
    similarity_threshold: 0.5,
    minimum_similarity_threshold: 0.5,
    scope: 'internal',
    metadata: {
      fileName: fileName,
    },
    body_metadata: {
      fileName: fileName,
    }
  } as any);
  console.log("Search response contexts count:", searchRes.contexts?.length || 0);
  if (searchRes.contexts && searchRes.contexts.length > 0) {
    console.log("Document STILL EXISTS!");
  } else {
    console.log("Document successfully DELETED!");
  }
}

main();

